const appSteps=['Personal details','Education','Programme & documents','Review'];
const allowedDocumentTypes=['application/pdf','image/jpeg','image/png'];
const maxDocumentBytes=5*1024*1024;
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));}
function validEmail(value){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);}
function applicationCompletion(){const a=state.application;let completed=0; if(a.fullName&&a.email&&a.country)completed++; if(a.qualification&&a.background)completed++; if(state.selectedCourse&&a.documentName)completed++; if(a.declaration)completed++; return completed;}
function selectApplicationStep(step){if(step<=applicationCompletion()){state.applicationStep=step;save();render();}else showToast('Complete the earlier stage first.');}
function renderApply(){
  const i=state.applicationStep;const c=currentCourse();const prefill=state.planner.location||'';const percent=Math.round(((i+1)/appSteps.length)*100);
  page(`<div class="section-head enrolment-heading"><div><span class="badge badge-blue">Application saved locally</span><p class="eyebrow">Online application</p><h1>Apply with confidence.</h1><p class="lead">Four clear stages, visible progress and no repeated information.</p></div><aside class="application-save-state"><span>Application progress</span><strong>${percent}%</strong><div class="ui-progress"><span style="width:${percent}%"></span></div><small>Your answers remain in this browser.</small></aside></div>
  <div class="application-layout">
    <aside class="application-nav">${appSteps.map((label,n)=>`<button class="${n===i?'active':n<i?'complete':''}" onclick="selectApplicationStep(${n})" ${n>applicationCompletion()?'disabled':''}><span>${n<i?'✓':n+1}</span><div><strong>${label}</strong><small>${['Contact and location','Background and entry context','Course and evidence','Confirm before payment'][n]}</small></div></button>`).join('')}<div class="application-help"><strong>Need assistance?</strong><p>Atlas can explain requirements without changing your application.</p><button class="btn btn-ghost" data-route="advisor">Ask Atlas</button></div></aside>
    <main class="form-card application-form-card"><div class="application-step-meta"><span>Step ${i+1} of ${appSteps.length}</span><span>${percent}% complete</span></div>${applicationStepHtml(i,c,prefill)}<div class="form-actions"><button class="btn btn-secondary" onclick="applicationBack()" ${i===0?'disabled':''}>Back</button><button class="btn btn-primary" onclick="applicationNext()">${i===appSteps.length-1?'Continue to payment':'Save and continue'} <span>→</span></button></div></main>
  </div>`)
}
function applicationStepHtml(i,c,prefill){
  const a=state.application;
  if(i===0)return `<p class="eyebrow">Personal details</p><h2>Tell us who you are.</h2><p class="form-intro">We use this information to create your application record and contact you about the next stage.</p><div class="form-grid two"><div class="field"><label for="fullName">Full name <span>*</span></label><input id="fullName" value="${escapeHtml(a.fullName||'')}" placeholder="Your full legal name" autocomplete="name"><small id="fullNameError" class="field-error"></small></div><div class="field"><label for="email">Email address <span>*</span></label><input id="email" type="email" value="${escapeHtml(a.email||'')}" placeholder="you@example.com" autocomplete="email"><small id="emailError" class="field-error"></small></div><div class="field"><label for="country">Country of residence <span>*</span></label><input id="country" value="${escapeHtml(a.country||prefill)}" placeholder="Country of residence" autocomplete="country-name"><small id="countryError" class="field-error"></small></div><div class="field"><label for="phone">Phone number</label><input id="phone" value="${escapeHtml(a.phone||'')}" placeholder="Include country code" autocomplete="tel"><small>Optional for the experience preview.</small></div></div>`;
  if(i===1)return `<p class="eyebrow">Education</p><h2>Help us understand your starting point.</h2><p class="form-intro">This supports eligibility review and helps tutors recommend the right level.</p><div class="field"><label for="qualification">Highest qualification <span>*</span></label><select id="qualification"><option value="">Select qualification</option>${['Secondary school','College or diploma','Bachelor degree','Postgraduate degree','Professional experience'].map(x=>`<option ${a.qualification===x||(!a.qualification&&state.planner.education===x)?'selected':''}>${x}</option>`).join('')}</select><small id="qualificationError" class="field-error"></small></div><div class="field"><label for="background">Education or professional background <span>*</span></label><textarea id="background" rows="6" maxlength="800" placeholder="Briefly describe relevant education, work or research experience">${escapeHtml(a.background||'')}</textarea><div class="field-foot"><small id="backgroundError" class="field-error"></small><small>Up to 800 characters</small></div></div>`;
  if(i===2)return `<p class="eyebrow">Programme and documents</p><h2>Confirm your chosen route.</h2><p class="form-intro">The programme carries forward from Atlas or the course catalogue and can still be changed here.</p><div class="field"><label for="programme">Selected programme <span>*</span></label><select id="programme">${courses.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.title}</option>`).join('')}</select></div><div class="selected-programme-summary"><div><span class="badge badge-blue">${c.category}</span><h3>${c.title}</h3><p>${c.mode} · ${c.duration}</p></div><strong>${c.fee}</strong></div><div class="upload-zone ${a.documentName?'has-file':''}" onclick="document.getElementById('document').click()"><input id="document" type="file" accept=".pdf,.jpg,.jpeg,.png" onchange="handleDocument(this.files[0])"><span class="upload-zone__icon">↑</span><div><strong>${a.documentName?escapeHtml(a.documentName):'Add a supporting document'}</strong><p>${a.documentName?`${formatBytes(a.documentSize)} · Ready for review`:'PDF, JPG or PNG · Maximum 5 MB'}</p></div><button type="button" class="btn btn-secondary">${a.documentName?'Replace':'Choose file'}</button></div><small id="documentError" class="field-error"></small><div class="alert"><span>i</span><div><strong>Demonstration privacy</strong><br><small>The browser validates the file, but no document is transmitted or uploaded.</small></div></div>`;
  const ref=state.applicationReference||'Created after payment';
  return `<p class="eyebrow">Review</p><h2>Check everything before payment.</h2><p class="form-intro">You can return to any completed stage and make corrections.</p><div class="review-groups"><section><div class="review-heading"><h3>Personal details</h3><button class="text-button" onclick="selectApplicationStep(0)">Edit</button></div><dl><div><dt>Name</dt><dd>${escapeHtml(a.fullName||'Not provided')}</dd></div><div><dt>Email</dt><dd>${escapeHtml(a.email||'Not provided')}</dd></div><div><dt>Country</dt><dd>${escapeHtml(a.country||prefill||'Not provided')}</dd></div><div><dt>Phone</dt><dd>${escapeHtml(a.phone||'Not provided')}</dd></div></dl></section><section><div class="review-heading"><h3>Education</h3><button class="text-button" onclick="selectApplicationStep(1)">Edit</button></div><dl><div><dt>Qualification</dt><dd>${escapeHtml(a.qualification||'Not provided')}</dd></div><div class="wide"><dt>Background</dt><dd>${escapeHtml(a.background||'Not provided')}</dd></div></dl></section><section><div class="review-heading"><h3>Programme</h3><button class="text-button" onclick="selectApplicationStep(2)">Edit</button></div><dl><div><dt>Programme</dt><dd>${escapeHtml(c.title)}</dd></div><div><dt>Tuition</dt><dd>${escapeHtml(c.fee)}</dd></div><div><dt>Document</dt><dd>${escapeHtml(a.documentName||'Not provided')}</dd></div><div><dt>Reference</dt><dd>${ref}</dd></div></dl></section></div><label class="declaration"><input id="declaration" type="checkbox" ${a.declaration?'checked':''}><span>I confirm that the information is accurate and agree to continue to the payment demonstration.</span></label><small id="declarationError" class="field-error"></small>`;
}
function formatBytes(bytes=0){if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1024/1024).toFixed(1)} MB`;}
function handleDocument(file){
  const error=document.getElementById('documentError');
  if(!file)return;
  if(!allowedDocumentTypes.includes(file.type)){if(error)error.textContent='Use a PDF, JPG or PNG file.';return;}
  if(file.size>maxDocumentBytes){if(error)error.textContent='The file must be 5 MB or smaller.';return;}
  state.application.documentName=file.name;state.application.documentType=file.type;state.application.documentSize=file.size;save();render();showToast('Document checked and added to the demo application.');
}
function applicationBack(){if(state.applicationStep>0){state.applicationStep--;save();render()}}
function fieldError(id,message){const el=document.getElementById(id);if(el)el.textContent=message||'';}
function applicationNext(){
  const i=state.applicationStep;const a=state.application;let ok=true;
  if(i===0){a.fullName=document.getElementById('fullName').value.trim();a.email=document.getElementById('email').value.trim();a.country=document.getElementById('country').value.trim();a.phone=document.getElementById('phone').value.trim();fieldError('fullNameError',a.fullName?'':'Enter your full name.');fieldError('emailError',validEmail(a.email)?'':'Enter a valid email address.');fieldError('countryError',a.country?'':'Enter your country of residence.');ok=Boolean(a.fullName&&validEmail(a.email)&&a.country);}
  if(i===1){a.qualification=document.getElementById('qualification').value;a.background=document.getElementById('background').value.trim();fieldError('qualificationError',a.qualification?'':'Select your highest qualification.');fieldError('backgroundError',a.background.length>=20?'':'Add at least 20 characters about your background.');ok=Boolean(a.qualification&&a.background.length>=20);}
  if(i===2){state.selectedCourse=document.getElementById('programme').value;fieldError('documentError',a.documentName?'':'Add one supporting document for the demonstration.');ok=Boolean(a.documentName);}
  if(i===3){a.declaration=document.getElementById('declaration').checked;fieldError('declarationError',a.declaration?'':'Confirm the declaration before continuing.');ok=a.declaration;}
  save();if(!ok)return showToast('Please check the highlighted information.');
  if(i<appSteps.length-1){state.applicationStep++;save();render();}else go('payment');
}

function renderPayment(){
  const c=currentCourse();const a=state.application;const paid=Boolean(state.paid);
  page(`<div class="payment-layout"><section class="form-card payment-card"><div class="payment-secure"><span>🔒</span><div><strong>Secure payment demonstration</strong><small>No card information leaves this browser.</small></div></div><p class="eyebrow">Confirm your place</p><h1>${paid?'Payment approved':'Complete the final step.'}</h1>${paid?`<div class="payment-approved"><span>✓</span><div><strong>Your demonstration payment is complete.</strong><p>Continue to your confirmation and Digital Campus.</p></div></div><button class="btn btn-primary" data-route="welcome">View confirmation</button>`:`<div class="field"><label for="cardName">Name on card</label><input id="cardName" value="${escapeHtml(a.fullName||'')}" autocomplete="cc-name"></div><div class="field"><label for="cardNumber">Card number</label><input id="cardNumber" inputmode="numeric" value="4242 4242 4242 4242" maxlength="19" autocomplete="cc-number"><small>Use the prefilled demonstration number.</small></div><div class="form-grid two"><div class="field"><label for="expiry">Expiry</label><input id="expiry" value="12/30" maxlength="5" autocomplete="cc-exp"></div><div class="field"><label for="cvc">CVC</label><input id="cvc" value="123" maxlength="4" inputmode="numeric" autocomplete="cc-csc"></div></div><small id="paymentError" class="field-error"></small><button class="btn btn-primary payment-submit" onclick="completePayment()">Pay ${c.fee} in demo mode</button><p class="payment-legal">This Experience Preview does not process money or retain card details.</p>`}</section><aside class="ui-card order-summary"><p class="eyebrow">Order summary</p><span class="badge badge-blue">${c.category}</span><h2>${c.title}</h2><div class="programme-summary-row"><small>Delivery</small><strong>${c.mode}</strong></div><div class="programme-summary-row"><small>Duration</small><strong>${c.duration}</strong></div><div class="programme-summary-row total"><small>Total</small><strong>${c.fee}</strong></div><div class="alert"><span>✓</span><div><strong>Application checked</strong><br><small>${escapeHtml(a.documentName||'Supporting document')} included.</small></div></div></aside></div>`)
}
function completePayment(){
  const number=(document.getElementById('cardNumber')?.value||'').replace(/\s/g,'');const name=document.getElementById('cardName')?.value.trim();const expiry=document.getElementById('expiry')?.value.trim();const cvc=document.getElementById('cvc')?.value.trim();
  if(!name||number!=='4242424242424242'||!/^(0[1-9]|1[0-2])\/\d{2}$/.test(expiry)||!/^\d{3,4}$/.test(cvc)){fieldError('paymentError','Use the prefilled demonstration card details and provide the cardholder name.');return showToast('Please check the payment details.');}
  state.paid=true;state.paymentDate=new Date().toISOString();state.applicationReference ||= `LLU-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;state.receiptReference=`RCT-${Math.random().toString(36).slice(2,9).toUpperCase()}`;save();showToast('Demo payment approved.');setTimeout(()=>go('welcome'),650);
}
