const researchPublications=[
  {id:'adaptive-governance',theme:'AI governance',title:'Adaptive governance for digital societies',author:'Dr Elena Marković',role:'Director of Digital Governance Research',date:'12 July 2026',read:'8 min read',status:'Working paper',abstract:'A practical governance model for institutions adopting artificial intelligence while preserving transparency, accountability and human agency.',keywords:['Artificial intelligence','Governance','Public institutions','Trust'],body:['Digital institutions need governance systems that can evolve at the same pace as the technologies they oversee. Static policy cycles are increasingly mismatched with adaptive systems, distributed decision-making and rapidly changing public expectations.','This paper proposes a layered model combining clear institutional principles, proportionate controls and continuous evidence review. It treats governance as an operating capability rather than a one-time compliance exercise.','The model is intended for universities, public institutions and digitally native communities seeking to adopt AI responsibly without slowing useful experimentation.']},
  {id:'borderless-participation',theme:'Digital statecraft',title:'Participation beyond borders',author:'Prof. Adrian Keller',role:'Chair of Digital Institutions',date:'28 June 2026',read:'11 min read',status:'Research brief',abstract:'How digital identity and community governance can support meaningful participation across geography, citizenship and institutional boundaries.',keywords:['Digital identity','Participation','Institutions','Community'],body:['Borderless communities are often described through technology, yet their long-term legitimacy depends on institutional design. Identity, rights, responsibilities and routes to participation must work together.','The research examines how digital identity can support trusted participation without reproducing unnecessary bureaucracy or excluding people with limited technical access.','The resulting framework prioritises progressive trust, clear consent and transparent institutional accountability.']},
  {id:'learning-futures',theme:'Learning futures',title:'From course catalogues to adaptive learning pathways',author:'Dr Sara Vuković',role:'Research Lead, Learning Futures',date:'4 June 2026',read:'9 min read',status:'Discussion paper',abstract:'A student-centred model for combining programme structure, intelligent guidance and human academic support.',keywords:['Adaptive learning','Student success','Guidance','Higher education'],body:['Students rarely experience education as a clean sequence of modules. Their goals, confidence and circumstances change over time. Digital campuses should respond without making the learning journey feel unpredictable.','This paper separates visible student choices from the intelligence operating behind them. The proposed model gives each learner one clear next step while preserving academic structure and human oversight.','The approach informs the design of Atlas, Liberland University’s guidance experience.']}
];
