function renderResearcher(){const r=researchers.find(x=>x.id===state.selectedResearcher)||researchers[0];const pubs=researchPublications.filter((p,i)=>p.author.includes(r.name.split(' ').slice(-1)[0])||i<2);page(`<div class="researcher-shell"><button class="rp-back" data-route="research">← Research Hub</button><header><div class="rh-avatar large">${r.initials}</div><div><p class="eyebrow">Researcher profile</p><h1>${r.name}</h1><p class="lead">${r.title}</p><p>${r.expertise}</p><button class="btn btn-primary" data-route="research-collaboration">Request collaboration →</button></div></header><div class="researcher-layout"><main><section><p class="eyebrow">Biography</p><h2>Research with practical relevance.</h2><p>${r.bio}</p></section><section><p class="eyebrow">Current interests</p><div class="rp-keywords">${r.expertise.split(' · ').map(x=>`<span>${x}</span>`).join('')}</div></section></main><aside><p class="eyebrow">Selected publications</p>${pubs.map(p=>`<button class="researcher-pub" onclick="openPublication('${p.id}')"><span>${p.theme}</span><strong>${p.title}</strong><small>${p.date} →</small></button>`).join('')}</aside></div></div>`)}
