// EP1 interaction and motion enhancements --------------------------------
const appRoot=document.getElementById('app');
const topbar=document.querySelector('.topbar');
const motionToggle=document.getElementById('motionToggle');
let revealObserver;

function prepareMotion(){
  appRoot.classList.remove('route-enter');
  void appRoot.offsetWidth;
  appRoot.classList.add('route-enter');
  requestAnimationFrame(()=>{
    const targets=appRoot.querySelectorAll('.section,.card,.panel,.form-card,.result-card,.process-step,.programme-hero,.research-hero,.callout');
    targets.forEach(el=>el.classList.add('reveal'));
    if(revealObserver) revealObserver.disconnect();
    revealObserver=new IntersectionObserver(entries=>{
      entries.forEach(entry=>{
        if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}
      });
    },{threshold:.08,rootMargin:'0px 0px -36px 0px'});
    targets.forEach(el=>revealObserver.observe(el));
  });
}

const baseRender=render;
render=function(){baseRender();prepareMotion();};

window.addEventListener('scroll',()=>topbar.classList.toggle('scrolled',window.scrollY>8),{passive:true});

const savedMotion=localStorage.getItem('ldcReduceMotion')==='true';
document.body.classList.toggle('reduce-motion',savedMotion);
motionToggle.textContent=savedMotion?'Motion: Off':'Motion: On';
motionToggle.setAttribute('aria-pressed',String(savedMotion));
motionToggle.addEventListener('click',()=>{
  const reduced=!document.body.classList.contains('reduce-motion');
  document.body.classList.toggle('reduce-motion',reduced);
  localStorage.setItem('ldcReduceMotion',String(reduced));
  motionToggle.textContent=reduced?'Motion: Off':'Motion: On';
  motionToggle.setAttribute('aria-pressed',String(reduced));
  showToast(reduced?'Motion reduced.':'Motion enabled.');
});

// Re-run once because the original script rendered before this enhancement loaded.
prepareMotion();
